use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let limit = 200001
    let mut sieve: Vec<bool> = []
    let mut cnt: Vec<int> = []
    let mut last: Vec<int> = []
    let mut i = 0
    while i < limit {
        sieve.push(true)
        cnt.push(0)
        last.push(-1)
        i += 1
    }
    let mut p = 2
    while p < limit {
        if sieve[p] {
            let mut m = p * 2
            while m < limit {
                sieve[m] = false
                m += p
            }
        }
        p += 1
    }
    let mut c = 0
    let mut l = -1
    let mut k = 0
    while k < limit {
        if k >= 2 && sieve[k] {
            c += 1
            l = k as int
        }
        cnt[k] = c
        last[k] = l
        k += 1
    }
    let mut first = true
    for line in text.lines() {
        let t = line.trim()
        if t == "" { continue }
        if first {
            first = false
            continue
        }
        let n: int = t.parse::<int>().unwrap_or(0)
        if last[n] < 0 {
            println("0 none")
        } else {
            println("${cnt[n]} ${last[n]}")
        }
    }
}

